import argparse
import concurrent.futures
import os
import sys
import xml.etree.ElementTree as ET
from datetime import datetime, timedelta
from hashlib import sha256

def parse_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    max_workers = int(root.attrib['max_workers'])
    min_interval_ms = int(root.attrib['min_interval_ms'])
    salt = root.find('salt').text
    return max_workers, min_interval_ms, salt.encode('utf-8')

def compute_fingerprint(file_path, salt):
    try:
        with open(file_path, 'rb') as f:
            file_bytes = f.read()
        combined = salt + file_bytes
        digest = sha256(combined).digest()
        return digest.hex()
    except (IOError, OSError):
        return 'ERROR'

def process_paths(max_workers, min_interval_ms, salt, paths):
    results = [None] * len(paths)
    futures = []
    start_time = None
    last_start_time = None

    def worker(path):
        nonlocal last_start_time
        if last_start_time and (datetime.now() - last_start_time) < timedelta(milliseconds=min_interval_ms):
            return 'ERROR'
        last_start_time = datetime.now()
        return compute_fingerprint(path, salt)

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        for i, path in enumerate(paths):
            future = executor.submit(worker, path)
            futures.append((future, i))

        for future, idx in futures:
            results[idx] = future.result()

    return results

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('config')
    args = parser.parse_args()

    max_workers, min_interval_ms, salt = parse_config(args.config)

    paths = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            paths.append(line)

    results = process_paths(max_workers, min_interval_ms, salt, paths)

    for path, result in zip(paths, results):
        print(f"{path}\t{result}")

if __name__ == "__main__":
    main()
